import { CommonModule } from '@angular/common';
import { Component, Input, OnInit } from '@angular/core';
import { FieldInputComponent } from '../field-input/field-input.component';
import { FormsFieldModel } from 'src/app/shared/models/forms-field.model';

@Component({
  selector: 'mf-forms-section',
  imports: [CommonModule, FieldInputComponent],
  templateUrl: './section.component.html',
  styleUrls: ['./section.component.scss'],
  standalone: true,
})
export class SectionComponent implements OnInit{
  private colors: string[] = [
      '#ffadad',
      '#ffd6a5',
      '#fdffb6',
      '#caffbf',
      '#9bf6ff',
      '#a0c4ff',
      '#bdb2ff',
      '#ffc6ff',
    ]
  currentColor: string = 'white';
  @Input() formsField!: FormsFieldModel;
  @Input() color!: number;
  outputColor: number = 0;
  constructor() {
  }
  ngOnInit(): void {
    this.currentColor = this.colors.at(this.color % 7)!;
    this.outputColor = this.color + 1;
  }
}
<div style="background-color: {{currentColor}}; padding: 0 0 0 10px">
  <p>forms-array works!</p>
  <p>{{formsField.contrato}}</p>
  <p>{{formsField.rotulo}}</p>
  <p>{{formsField.tipo_dado}}</p>
  <ng-container *ngFor="let item of formsField.conteudo">
    <ng-container *ngIf="item.tipo_dado === 'string'">
      <mf-forms-field-input [formsField]="item" [color]="outputColor"></mf-forms-field-input>
    </ng-container>
    <ng-container *ngIf="item.tipo_dado in ['array', 'object']">
      <mf-forms-section [formsField]="item" [color]="outputColor"></mf-forms-section>
    </ng-container>
  </ng-container>
</div>
